document.addEventListener("click", (e) => {
  const zoom = e.target.closest("[data-zoom]");
  if (zoom) {
    const expanded = $("#dialog").classList.toggle("image-zoomed");
    zoom.setAttribute("aria-pressed", String(expanded));
    zoom.setAttribute("aria-label", expanded ? "Fit original item image" : "Enlarge original item image");
    zoom.querySelector("span").textContent = expanded ? "Click to fit" : "Click to zoom";
    return;
  }
  const a = e.target.closest("[data-add]"), d = e.target.closest("[data-detail]"), r = e.target.closest("[data-remove]");
  if (a) add(a.dataset.add);
  if (d) detail(d.dataset.detail);
  if (r) {
    cart().delete(r.dataset.remove);
    render();
    review();
  }
  if (["slotStats", "emptyStats"].includes(e.target.id)) stats();
  if (e.target.id === "unown") toggleOwned();
  if (e.target.id === "undo" && undoAction) {
    undoAction();
    undoAction = null;
    $("#toast").classList.remove("show");
  }
  if (e.target.id === "acceptRecommendation") {
    const p = state.proposal, count = p.size, c = cart(), context2 = key();
    for (const [id, item] of p) if (!c.has(id) && !owned().has(id)) c.set(id, item);
    state.proposal = null;
    render();
    toast(count + " recommended items added", () => {
      for (const [id, item] of p) if (c.get(id)?.id === item.id) c.delete(id);
      if (key() === context2) render();
    });
  }
  if (e.target.id === "cancelRecommendation") {
    state.proposal = null;
    render();
  }
  if (e.target.id === "export") {
    const data = { build: build().name, source: build().source?.url, realm: state.realm, sampleOnly: true, socketItems: socketShop.exportItems(), items: [...cart().values()].map((p) => ({ itemNumber: itemNumber(p) ? "#" + itemNumber(p) : null, name: cleanItemName(p), slot: p.slotLabel, price: p.price })) };
    const url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }));
    const a2 = document.createElement("a");
    a2.href = url;
    a2.download = "mmoexp-loadout.json";
    a2.click();
    URL.revokeObjectURL(url);
  }
});
